class Solution {
    static int ncr_modp(int n, int r, int p) {
        int[] C = new int[r+1];
        C[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = Math.min(i, r); j > 0; j--) {
                C[j] = (C[j] + C[j-1]) % p;
            }
        }
