        for (let j = i + 1; j < n; j++) {
            // Calculate the absolute difference between arr[i] and arr[j]
            const diff = Math.abs(arr[i] - arr[j]);
            // Add the difference to the sum
            sum += diff;
        }
    }

    return sum;
}

